/**
 * SAILING (1983 - DYNETRON COMPANY)
 * Authentic IBM PC Speaker (1-Bit Intel 8253 PIT) Audio Emulation
 *
 * Emulates the pure square-wave audio generated by the 8253 timer on original DOS PCs.
 * No continuous modern noise filters — sound is event-driven and strictly period-accurate.
 */

class V1Audio {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.initialized = false;
    this.lastLuffSound = 0;
  }

  init() {
    if (this.initialized) return;
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (AudioContext) {
        this.ctx = new AudioContext();
        this.initialized = true;
      }
    } catch (e) {
      console.warn("Web Audio API unavailable:", e);
    }
  }

  resume() {
    if (!this.initialized) this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  toggleMute() {
    this.enabled = !this.enabled;
    return this.enabled;
  }

  tone(freq, duration, vol = 0.16) {
    if (!this.enabled || !this.ctx) return;
    this.resume();
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'square'; // Exact PC Speaker 1-bit waveform
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

      gain.gain.setValueAtTime(vol, this.ctx.currentTime);
      gain.gain.setValueAtTime(0.001, this.ctx.currentTime + duration);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start();
      osc.stop(this.ctx.currentTime + duration);
    } catch (e) {}
  }

  // Quick crisp UI / key click
  beepClick() {
    this.tone(980, 0.02, 0.1);
  }

  // Sail sheet trimming click
  sheetClick() {
    this.tone(720, 0.015, 0.08);
  }

  // Violent gybe: heavy boom snap across centerline
  gybeClack() {
    this.tone(160, 0.04, 0.25);
    setTimeout(() => this.tone(95, 0.06, 0.3), 35);
  }

  // In-irons luffing: sail fluttering in headwind
  luffFlutter() {
    const now = performance.now();
    if (now - this.lastLuffSound > 180) {
      this.lastLuffSound = now;
      this.tone(110 + Math.random() * 40, 0.035, 0.12);
    }
  }

  // Swimmer rescued ding
  rescueDing() {
    this.tone(587, 0.08, 0.22);
    setTimeout(() => this.tone(880, 0.14, 0.22), 80);
  }

  // Collision crunch / thud
  crashThud() {
    const notes = [130, 98, 73, 55];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.05, 0.28), i * 45);
    });
  }

  // Sector flip tick
  sectorFlipTick() {
    this.tone(1200, 0.02, 0.12);
  }

  // Leg start fanfare
  legStart() {
    const notes = [440, 554, 659, 880];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.07, 0.18), i * 80);
    });
  }

  // Port arrival fanfare
  portVictory() {
    const notes = [523, 659, 784, 1046];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.12, 0.22), i * 110);
    });
  }

  // Game over somber descending tones
  gameOver() {
    const notes = [440, 370, 311, 220];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.25, 0.25), i * 220);
    });
  }

  // Hazard alerts
  whirlwindWarp() {
    for (let i = 0; i < 8; i++) {
      const f = 250 + (i % 2 === 0 ? 300 : -100);
      setTimeout(() => this.tone(f, 0.035, 0.15), i * 40);
    }
  }

  anomalyChime() {
    const notes = [988, 1318, 1760];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.06, 0.12), i * 60);
    });
  }
}

if (typeof window !== 'undefined') {
  window.v1Audio = new V1Audio();
}
